					for (const r of details.results) {
						const rIcon = r.exitCode === 0 ? theme.fg("success", "вњ?) : theme.fg("error", "вњ?);
						const displayItems = getDisplayItems(r.messages);
						const finalOutput = getFinalOutput(r.messages);

						container.addChild(new Spacer(1));
						container.addChild(
							new Text(
								`${theme.fg("muted", `в”Ђв”Ђв”Ђ Step ${r.step}: `) + theme.fg("accent", r.agent)} ${rIcon}`,
